stylesheets.stylesheet:
/* ===== I-Forge RPG - Brutalist Manga Theme ===== */
@import url('https://fonts.googleapis.com/css2?family=Permanent+Marker&display=swap');

:root {
  --bg: #f4f0e6;
  --bg-dark: #ebe6d6;
  --panel: #2d5a27;
  --panel-hover: #3d7a35;
  --gold: #c9a84c;
  --gold-hover: #e2c96b;
  --ink: #1a1a1a;
  --ink-secondary: #5a5a4a;
  --border: #1e3d1a;
  --shadow: 3px 3px 0 #1e3d1a;
  --shadow-hover: 4px 4px 0 #1e3d1a;
  --radius: 3px;
  --font-brush: 'Permanent Marker', 'Comic Sans MS', 'Chalkboard SE', cursive;
  --font-serif: Georgia, 'Palatino Linotype', 'Times New Roman', serif;
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  background: var(--bg) url('https://i.imgur.com/9lVReZ1.jpeg') center top fixed !important;
  background-size: cover !important;
  color: var(--ink) !important;
  font-family: var(--font-serif) !important;
  font-size: 15px;
  line-height: 1.5;
}
body { padding-top: 56px; }

img.icon { width: 14px; height: 14px; vertical-align: middle; }
img { max-width: 100%; height: auto; }

a { color: var(--gold); text-decoration: none; font-weight: 600; transition: color 0.15s; }
a:hover { color: var(--gold-hover); }

/* Hide MyBB clutter */
#header, #logo, #panel, .welcomeblock, .upper, .modal,
.navigation, #footer, .bottom_links, .theme, #theme_select,
#copyright, .lower, #debug {
  display: none !important;
}

#container, #content, .content, .container, .wrapper, #wrapper, #main {
  background: transparent !important;
  max-width: none !important;
  width: 100% !important;
  padding: 0 !important;
  margin: 0 !important;
}

/* MyBB table defaults */
.tborder, .tcat, .thead, .trow1, .trow2, tbody, .panel, .post, .post_content, .postbit, #posts, .pagination, .forumdisplay, .threadlist {
  background: transparent !important;
  border-color: var(--border) !important;
}
.tcat, .thead {
  background: var(--panel) !important;
  color: var(--gold) !important;
  border: 3px solid var(--border) !important;
  box-shadow: var(--shadow) !important;
}
.tborder { border: 3px solid var(--border) !important; }

/* Navbar fixed - outside container */
#iforge-navbar {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  z-index: 10000 !important;
  background: var(--panel);
  border-bottom: 3px solid var(--border);
  box-shadow: var(--shadow);
}
.iforge-nav {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  height: 56px;
  padding: 0 16px;
  position: relative;
}
.iforge-nav-left { display: flex; align-items: center; gap: 24px; }
.iforge-nav-logo {
  position: absolute;
  left: 16px;
  font-family: var(--font-brush);
  font-size: 1.4rem;
  color: var(--gold);
  letter-spacing: 2px;
  text-transform: uppercase;
  text-shadow: 2px 2px 0 var(--border);
}
.iforge-nav-logo:hover { color: var(--gold-hover); }
.iforge-nav-link {
  color: #fff;
  font-family: var(--font-sans);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 4px 0;
  position: relative;
}
.iforge-nav-link:hover { color: var(--gold-hover); }
.iforge-nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px; left: 0; right: 0;
  height: 3px;
  background: var(--gold);
  transform: scaleX(0);
  transition: transform 0.2s;
}
.iforge-nav-link:hover::after { transform: scaleX(1); }
.iforge-nav-right { position: absolute; right: 16px; }
.iforge-user-btn {
  background: var(--panel-hover);
  border: 3px solid var(--border);
  border-radius: 50%;
  width: 36px; height: 36px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--gold);
  font-weight: 700;
  box-shadow: 2px 2px 0 var(--border);
}
.iforge-user-btn:hover { background: var(--gold); color: var(--panel); }
.iforge-dropdown {
  display: none;
  position: absolute;
  right: 0; top: 46px;
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  min-width: 180px;
  overflow: hidden;
}
.iforge-dropdown.open { display: block; }
.iforge-dropdown-item {
  display: block;
  padding: 8px 14px;
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 0.8rem;
  font-weight: 600;
  border-bottom: 2px solid var(--border);
  transition: background 0.15s;
}
.iforge-dropdown-item:last-child { border-bottom: none; }
.iforge-dropdown-item:hover { background: var(--gold); color: var(--panel); }
.iforge-dropdown-divider { border: none; border-top: 2px solid var(--border); margin: 0; }

/* Banner */
#iforge-banner {
  position: relative;
  width: 100%;
  height: 300px;
  overflow: hidden;
  background-size: cover;
  background-position: center;
  border-bottom: 3px solid var(--border);
  box-shadow: var(--shadow);
  display: flex;
  align-items: center;
  justify-content: center;
}
#iforge-banner::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(244,240,230,0.25) 0%, rgba(30,61,26,0.6) 100%);
}
.iforge-banner-seal {
  position: absolute;
  z-index: 1;
  color: rgba(30,61,26,0.14);
  font-size: 200px;
  pointer-events: none;
  font-family: var(--font-brush);
  user-select: none;
  letter-spacing: 4px;
}
.iforge-banner-content { position: relative; z-index: 2; text-align: center; }
.iforge-banner-title {
  font-family: var(--font-brush);
  font-size: 3rem;
  color: var(--gold);
  letter-spacing: 5px;
  text-transform: uppercase;
  text-shadow: 3px 3px 0 var(--border), -1px -1px 0 rgba(255,255,255,0.3);
  margin-bottom: 6px;
}
.iforge-banner-subtitle {
  font-family: var(--font-serif);
  font-size: 1rem;
  color: #fff;
  letter-spacing: 3px;
  font-weight: 700;
  text-shadow: 2px 2px 0 var(--border);
}

/* Calendar bar */
#iforge-calendar-bar {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--panel);
  border-bottom: 3px solid var(--border);
  box-shadow: var(--shadow);
  font-family: var(--font-sans);
  font-size: 0.78rem;
  color: #fff;
  letter-spacing: 1px;
  text-transform: uppercase;
  font-weight: 700;
  cursor: pointer;
}
#iforge-calendar-bar:hover { background: var(--panel-hover); }
#iforge-calendar-bar .icon { width: 14px; height: 14px; filter: brightness(0) invert(1); }
#iforge-calendar-bar strong { color: var(--gold); }

/* ===== TABLON ===== */
.iforge-tablon {
  max-width: 1200px;
  margin: 16px auto 0;
  padding: 0 16px;
  display: grid;
  grid-template-columns: 1fr 1.2fr 1fr;
  gap: 12px;
  align-items: start;
}
.iforge-tablon-col {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.iforge-tablon-title {
  font-family: var(--font-brush);
  font-size: 2rem;
  color: var(--panel);
  text-transform: uppercase;
  line-height: 1;
  margin-bottom: 0;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 var(--gold);
}
.iforge-tablon-title span {
  display: block;
  color: var(--gold);
  text-shadow: 2px 2px 0 var(--panel);
}
.iforge-tablon-box {
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  overflow: hidden;
}
.iforge-tablon-box-header {
  padding: 8px 12px;
  font-family: var(--font-brush);
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gold);
  background: var(--panel);
  border-bottom: 3px solid var(--border);
}
.iforge-tablon-box-body {
  padding: 10px;
  min-height: 80px;
}
.iforge-tablon-box-body:empty::after {
  content: 'Vacío por ahora...';
  display: block;
  color: var(--ink-secondary);
  font-style: italic;
  text-align: center;
  padding: 16px 0;
}
.iforge-tablon-item {
  padding: 6px 0;
  border-bottom: 2px dashed var(--border);
  color: var(--ink);
  font-size: 0.85rem;
  font-weight: 600;
}
.iforge-tablon-item:last-child { border-bottom: none; }
.iforge-tablon-item-meta {
  font-size: 0.72rem;
  color: var(--ink-secondary);
  font-family: var(--font-sans);
  margin-top: 2px;
}
.iforge-ambientacion {
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 14px;
  color: #fff;
}
.iforge-ambientacion-label {
  font-family: var(--font-sans);
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--gold);
  margin-bottom: 2px;
}
.iforge-ambientacion-title {
  font-family: var(--font-brush);
  font-size: 1.5rem;
  color: var(--gold);
  text-transform: uppercase;
  margin-bottom: 8px;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 var(--border);
}
.iforge-ambientacion-text {
  font-size: 0.85rem;
  line-height: 1.5;
  color: #fff !important;
}
.iforge-quick-links {
  background: var(--bg-dark);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  padding: 10px;
}
.iforge-quick-links-title {
  font-family: var(--font-brush);
  font-size: 0.9rem;
  color: var(--panel);
  text-transform: uppercase;
  margin-bottom: 8px;
  letter-spacing: 1px;
}
.iforge-quick-links-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px;
}
.iforge-quick-link {
  display: block;
  padding: 5px 8px;
  background: var(--bg);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--panel);
  text-transform: uppercase;
  transition: background 0.15s;
}
.iforge-quick-link:hover { background: var(--gold); color: var(--panel); }

/* Tabs */
.iforge-tabs {
  display: flex;
  gap: 6px;
}
.iforge-tab {
  flex: 1;
  padding: 8px 4px;
  background: var(--panel);
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  color: #fff;
  font-family: var(--font-brush);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.15s;
}
.iforge-tab:hover, .iforge-tab.active {
  background: var(--gold);
  color: var(--panel);
}

#iforge-next-curiosidad {
  cursor: pointer;
  color: var(--panel);
  display: inline-block;
  margin-top: 6px;
  font-size: 0.75rem;
  font-family: var(--font-sans);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 3px 10px;
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  transition: background 0.15s;
}
#iforge-next-curiosidad:hover { background: var(--gold); color: var(--panel); }

/* Staff */
.iforge-staff-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 10px;
}
.iforge-staff-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  background: var(--bg);
  border: 3px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-size: 0.8rem;
  font-family: var(--font-sans);
  font-weight: 600;
}
.iforge-staff-mp {
  color: var(--ink-secondary);
  font-size: 0.7rem;
  padding: 2px 6px;
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
  border-radius: var(--radius);
  font-weight: 700;
}
.iforge-staff-mp:hover { background: var(--gold); color: var(--panel); }

/* ===== CATEGORIES WITH FORUMS ===== */
.iforge-categories {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.iforge-categories > table {
  width: 100% !important;
  border-collapse: separate;
  border-spacing: 0;
  background: var(--bg-dark) !important;
  border: 3px solid var(--border);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
  overflow: hidden;
}
.iforge-categories > table > thead,
.iforge-categories > table > tbody,
.iforge-categories > table > tfoot,
.iforge-categories > table tr,
.iforge-categories > table td {
  display: block;
  width: 100%;
}
.iforge-categories .tcat,
.iforge-categories .thead {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  background: var(--panel) !important;
  color: var(--gold) !important;
  font-family: var(--font-brush);
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  border-bottom: 3px solid var(--border) !important;
  box-shadow: none !important;
}
.iforge-categories .tcat::before {
  content: '▶';
  color: var(--gold);
  font-size: 0.7rem;
}
.iforge-categories .trow1,
.iforge-categories .trow2 {
  background: var(--bg) !important;
  border-bottom: 2px dashed var(--border) !important;
  padding: 10px 14px;
  transition: background 0.15s;
}
.iforge-categories .trow1:last-child,
.iforge-categories .trow2:last-child {
  border-bottom: none !important;
}
.iforge-categories .trow1:hover,
.iforge-categories .trow2:hover {
  background: rgba(201,168,76,0.12) !important;
}
.iforge-categories .trow1 a,
.iforge-categories .trow2 a {
  color: var(--panel) !important;
  font-weight: 700;
  font-size: 0.95rem;
}
.iforge-categories .trow1 .smalltext,
.iforge-categories .trow2 .smalltext {
  color: var(--ink-secondary);
  font-size: 0.75rem;
  margin-top: 3px;
}

/* Footer */
#iforge-footer {
  background: var(--panel);
  border-top: 3px solid var(--border);
  box-shadow: var(--shadow);
  padding: 16px;
  text-align: center;
  color: #fff;
  font-size: 0.75rem;
  font-family: var(--font-sans);
  font-weight: 600;
  letter-spacing: 0.5px;
  margin-top: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}
#iforge-footer .seal { width: 18px; height: 18px; opacity: 0.6; filter: brightness(0) invert(1); }
#iforge-footer a { color: var(--gold); }
#iforge-footer a:hover { color: var(--gold-hover); }

/* Badges */
.iforge-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 3px;
  font-size: 0.65rem;
  font-weight: 800;
  margin-right: 4px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  font-family: var(--font-sans);
  border: 2px solid var(--border);
  box-shadow: 2px 2px 0 var(--border);
}

/* Responsive */
@media (max-width: 900px) {
  .iforge-tablon { grid-template-columns: 1fr; }
  .iforge-banner-title { font-size: 2.2rem; }
  #iforge-banner { height: 220px; }
  .iforge-nav-left { gap: 14px; }
  .iforge-nav-link { font-size: 0.72rem; }
}
@media (max-width: 600px) {
  .iforge-banner-title { font-size: 1.8rem; }
  .iforge-tablon-title { font-size: 1.6rem; }
  .iforge-nav { padding: 0 10px; }
  .iforge-nav-logo { font-size: 1.1rem; left: 10px; }
  .iforge-nav-right { right: 10px; }
  .iforge-quick-links-grid { grid-template-columns: 1fr; }
}
